head.script:
// 전역 변수
scwin.CURRENT_PROJECT_ID = "";
scwin.CURRENT_USER_ID = "";
scwin.currentMode = "new"; // new, edit, view


/**
 * 페이지 로드 시 초기화
 */
scwin.onpageload = function() {
    console.log("단위테스트 팝업 로드");

    // 초기화
    scwin.initializeData();

    // 사용자 정보 가져오기 (Test.xml과 동일한 방식)
    scwin.getCurrentUserInfo();

    // 부모 창에서 프로젝트 ID 가져오기
    scwin.getProjectIdFromParent();

    // 사용자 이름 가져오기 테스트
    var userName = scwin.getCurrentUserName();
    console.log("=== 사용자 정보 최종 확인 ===");
    console.log("CURRENT_USER_ID:", scwin.CURRENT_USER_ID);
    console.log("USER_NAME:", userName);
    console.log("CURRENT_PROJECT_ID:", scwin.CURRENT_PROJECT_ID);

    // 부모창에서 전달받은 데이터 처리
    scwin.initializeFromParentData();

    // 모드에 따른 초기화
    scwin.initializeByMode();

    console.log("팝업 로드 완료");
};

/**
 * UnitTestPopup.xml용 데이터 초기화
 */
scwin.initializeData = function() {
    console.log("팝업 데이터 초기화 시작");

    // 전역 변수 초기화
    scwin.CURRENT_PROJECT_ID = "";
    scwin.CURRENT_USER_ID = "";
    scwin.CURRENT_USER_GROUP_ID = "";
    scwin.currentMode = "new"; // new, edit, view

    // 데이터맵 초기화
    try {
        dmp_unitTestDetail.setEmptyValue();
        dmp_taskSearch.setEmptyValue();
        dmp_currentFile.setEmptyValue();

        // 데이터리스트 초기화
        dlt_taskList.setJSON([]);
        dlt_attVoList.setJSON([]);
        dlt_upload.setJSON([]);

        console.log("데이터맵 및 데이터리스트 초기화 완료");
    } catch (e) {
        console.error("데이터 초기화 중 오류:", e);
    }

    // 파일 관련 초기화
    try {
        if (typeof mpd_html5Type !== 'undefined' && mpd_html5Type) {
            if (mpd_html5Type.clear) {
                mpd_html5Type.clear();
            } else if (mpd_html5Type.removeAllFiles) {
                mpd_html5Type.removeAllFiles();
            } else if (mpd_html5Type.fileArray) {
                mpd_html5Type.fileArray = [];
            }
        }
        console.log("파일 업로드 컴포넌트 초기화 완료");
    } catch (e) {
        console.error("파일 업로드 컴포넌트 초기화 실패:", e);
    }

    // 미리보기 패널 초기화
    try {
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        console.log("미리보기 패널 초기화 완료");
    } catch (e) {
        console.error("미리보기 패널 초기화 실패:", e);
    }

    // 에디터 초기화 (나중에 실행)
    setTimeout(function() {
        try {
            if (typeof editor_description !== 'undefined' && editor_description && editor_description.setHTML) {
                editor_description.setHTML("");
            }
            if (typeof editor_testData !== 'undefined' && editor_testData && editor_testData.setHTML) {
                editor_testData.setHTML("");
            }
            console.log("에디터 초기화 완료");
        } catch (e) {
            console.error("에디터 초기화 실패:", e);
        }
    }, 100);

    console.log("팝업 데이터 초기화 완료");
};

/**
 * 미리보기 패널 숨기기
 */
scwin.hideAllPreviewPanels = function() {
    try {
        if (typeof grp_noPreview !== 'undefined' && grp_noPreview && grp_noPreview.hide) {
            grp_noPreview.hide();
        }
        if (typeof grp_imagePreview !== 'undefined' && grp_imagePreview && grp_imagePreview.hide) {
            grp_imagePreview.hide();
        }
        if (typeof grp_textPreview !== 'undefined' && grp_textPreview && grp_textPreview.hide) {
            grp_textPreview.hide();
        }
        if (typeof grp_documentPreview !== 'undefined' && grp_documentPreview && grp_documentPreview.hide) {
            grp_documentPreview.hide();
        }
    } catch(e) {
        console.error("미리보기 패널 숨기기 오류:", e);
    }
};



/**
 * 부모창에서 전달받은 데이터 처리
 */
scwin.initializeFromParentData = function() {
    try {
        // 1. 표준 방식으로 파라미터 가져오기
        var paramData = $p.getParameter();
        console.log("팝업 파라미터 전체:", paramData);

        // 2. getParameter()가 undefined인 경우 대안 방법들 시도
        if (!paramData) {
            console.log("getParameter()가 undefined, 대안 방법들 시도");

            // 방법 1: parent window에서 직접 확인
            try {
                var parent = $p.getParentWindow();
                if (parent && parent.tempPopupData) {
                    paramData = parent.tempPopupData;
                    console.log("parent.tempPopupData에서 가져온 데이터:", paramData);
                }
            } catch(e) {
                console.log("parent window 방법 실패:", e);
            }

            // 방법 2: window에서 확인
            if (!paramData && window.tempPopupData) {
                paramData = window.tempPopupData;
                console.log("window.tempPopupData에서 가져온 데이터:", paramData);
            }
        }

        // 3. paramData 구조 확인 및 처리
        if (paramData) {
            console.log("파라미터 데이터 구조 확인:", paramData);

            // detailData가 있는 경우 (조회/수정 모드)
            if (paramData.detailData) {
                var detailData = paramData.detailData;
                console.log("전달받은 detailData:", detailData);

                scwin.currentMode = detailData.mode || "view";
                scwin.CURRENT_PROJECT_ID = detailData.pjtId || "";
                scwin.CURRENT_USER_ID = detailData.currentUserId || "1";

                if (detailData.testData) {
                    console.log("상세 데이터 설정:", detailData.testData);
                    dmp_unitTestDetail.setJSON(detailData.testData);

                    if (scwin.currentMode === "view" || scwin.currentMode === "edit") {
                        setTimeout(function() {
                            console.log("서버에서 상세 데이터 재조회 시작");
                            $c.sbm.execute($p, sbm_selectUnitTestDetail);
                        }, 100);
                    } else {
                        setTimeout(function() {
                            scwin.setEditorContent(
                                detailData.testData.description || "", 
                                detailData.testData.testData || ""
                            );
                        }, 300);
                    }
                }
            } 
            // taskData가 있는 경우 (등록 모드)
            else if (paramData.taskData) {
                var taskData = paramData.taskData;
                console.log("전달받은 taskData:", taskData);

                scwin.currentMode = taskData.mode || "new";
                scwin.CURRENT_PROJECT_ID = taskData.pjtId || "";
                scwin.CURRENT_USER_ID = taskData.currentUserId || "1";

                if (scwin.currentMode === "new") {
                    console.log("등록 모드 - 업무 정보 설정:");
                    console.log("- taskId:", taskData.taskId);
                    console.log("- taskName:", taskData.taskName);

                    // 업무 정보 설정 (업무명을 입력 필드에 표시)
                    dmp_unitTestDetail.set("taskId", taskData.taskId || "");
                    dmp_unitTestDetail.set("taskName", taskData.taskName || ""); // 중요: 업무명 설정
                    dmp_unitTestDetail.set("assignee", scwin.CURRENT_USER_ID);
                    dmp_unitTestDetail.set("assigneeName", taskData.currentUserName || scwin.getCurrentUserName() || "현재 사용자");
                    dmp_unitTestDetail.set("pjtId", scwin.CURRENT_PROJECT_ID);

                    console.log("등록 모드 - 설정 완료:");
                    console.log("- taskId:", taskData.taskId);
                    console.log("- taskName:", taskData.taskName, "(입력 필드에 표시됨)");
                    console.log("- assigneeName:", taskData.currentUserName);
                }
            }
            // 직접 데이터가 전달된 경우
            else if (paramData.data) {
                console.log("직접 데이터 전달됨:", paramData.data);
                var directData = paramData.data;

                if (directData.taskId && directData.taskName) {
                    scwin.currentMode = "new";
                    scwin.CURRENT_PROJECT_ID = directData.pjtId || "";
                    scwin.CURRENT_USER_ID = directData.currentUserId || "1";

                    console.log("직접 데이터로 업무 정보 설정:");
                    console.log("- taskId:", directData.taskId);
                    console.log("- taskName:", directData.taskName);

                    dmp_unitTestDetail.set("taskId", directData.taskId);
                    dmp_unitTestDetail.set("taskName", directData.taskName); // 업무명 설정
                    dmp_unitTestDetail.set("assignee", scwin.CURRENT_USER_ID);
                    dmp_unitTestDetail.set("assigneeName", directData.currentUserName || "현재 사용자");
                    dmp_unitTestDetail.set("pjtId", scwin.CURRENT_PROJECT_ID);
                }
            }
        } else {
            console.log("파라미터 데이터가 없음, 기본 등록 모드로 설정");
            scwin.currentMode = "new";
        }

        console.log("최종 설정된 값들:");
        console.log("현재 모드:", scwin.currentMode);
        console.log("프로젝트 ID:", scwin.CURRENT_PROJECT_ID);
        console.log("사용자 ID:", scwin.CURRENT_USER_ID);
        console.log("업무명 (입력 필드):", dmp_unitTestDetail.get("taskName"));

        // 임시 데이터 정리
        try {
            if (window.tempPopupData) {
                delete window.tempPopupData;
            }
            var parent = $p.getParentWindow();
            if (parent && parent.tempPopupData) {
                delete parent.tempPopupData;
            }
        } catch(e) {
            console.log("임시 데이터 정리 실패:", e);
        }

    } catch (e) {
        console.error("부모창 데이터 처리 실패:", e);
        scwin.currentMode = "new";
    }
};
/**
 * 모드에 따른 초기화
 */
scwin.initializeByMode = function() {
    console.log("모드별 초기화:", scwin.currentMode);

    // 파일 관련 초기화
    dlt_upload.setJSON([]);
    dlt_attVoList.setJSON([]);

    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();

    // 모드별 설정
    switch (scwin.currentMode) {
        case "new":
            scwin.initializeNewMode();
            break;
        case "edit":
            scwin.initializeEditMode();
            break;
        case "view":
            scwin.initializeViewMode();
            break;
        default:
            scwin.initializeNewMode();
    }
};

/**
 * 등록 모드 초기화
 */
scwin.initializeNewMode = function() {
    console.log("등록 모드 초기화 - 시연용 데이터 포함");

    // 기본값 설정
    if (!dmp_unitTestDetail.get("testStatus")) {
        dmp_unitTestDetail.set("testStatus", "SUC");
    }
    if (!dmp_unitTestDetail.get("priority")) {
        dmp_unitTestDetail.set("priority", "HIGH"); // 시연용: 높음으로 설정
    }
    if (!dmp_unitTestDetail.get("testType")) {
        dmp_unitTestDetail.set("testType", "NORMAL");
    }

    // 사용자 정보 가져오기
    var currentUserId = scwin.CURRENT_USER_ID || "1";
    var currentUserName = scwin.getCurrentUserName(); // 실제 사용자명 가져오기

    console.log("담당자 정보 설정:");
    console.log("- USER_ID:", currentUserId);
    console.log("- USER_NAME:", currentUserName);

    // 담당자는 사용자 ID로 저장하지만, 화면에는 사용자명으로 표시
    dmp_unitTestDetail.set("assignee", currentUserId); // 저장용 ID
    dmp_unitTestDetail.set("assigneeName", currentUserName); // 화면 표시용 이름

    // 프로젝트 ID 설정
    var projectId = scwin.CURRENT_PROJECT_ID;
    dmp_unitTestDetail.set("pjtId", projectId);

    // ===== 시연용 데이터 미리 입력 =====

    // 기존 업무명이 없는 경우에만 시연용 데이터 설정
    var existingTaskName = dmp_unitTestDetail.get("taskName");
    if (!existingTaskName || existingTaskName === "") {
        dmp_unitTestDetail.set("taskName", "별점 기능 개발");
    }

    // 시연용 테스트 케이스 정보 설정
    dmp_unitTestDetail.set("testCaseName", "기존 별점 업데이트 성공");
    dmp_unitTestDetail.set("testTarget", "updateProductRating(productId, userId, newRating)");
    dmp_unitTestDetail.set("testType", "NORMAL");
    dmp_unitTestDetail.set("priority", "HIGH");
    dmp_unitTestDetail.set("duration", "25"); // 20-30분의 중간값
    dmp_unitTestDetail.set("executionDate", "2025-07-30"); // 시연용 실행일시

    // 시연용 상세 설명 (HTML 형태)
    var demoDescription = `
        <p><strong>테스트 목적:</strong></p>
        <p>사용자가 이미 등록한 별점을 새로운 값으로 수정할 때 정상적으로 업데이트되는지 확인한다.</p>

        <p><strong>검증 항목:</strong></p>
        <ul>
            <li>기존 별점 데이터가 새로운 값으로 변경되는지 확인</li>
            <li>상품의 평균 별점이 올바르게 재계산되는지 검증</li>
            <li>수정 일시(updatedAt)가 현재 시간으로 갱신되는지 확인</li>
            <li>수정 이력이 로그에 기록되는지 확인</li>
        </ul>

        <p><strong>테스트 절차:</strong></p>
        <ol>
            <li>기존 별점이 등록된 상품 선택 (productId: PROD-2024-200)</li>
            <li>해당 사용자의 기존 별점 확인 (현재: 3점)</li>
            <li>새로운 별점으로 수정 요청 (변경: 5점)</li>
            <li>별점 업데이트 결과 검증</li>
            <li>상품 평균 별점 재계산 결과 확인</li>
        </ol>
    `;

    // 시연용 테스트 데이터 (JSON 형태)
    var demoTestData = `
        <p><strong>입력 데이터:</strong></p>
        <pre><code>{
  "input": {
    "productId": "PROD-2024-200",
    "userId": "USER-54321",
    "newRating": 5
  },
  "mockData": {
    "existingRating": {
      "ratingId": "RATING-2024-100",
      "productId": "PROD-2024-200",
      "userId": "USER-54321",
      "rating": 3,
      "createdAt": "2024-01-10T09:00:00Z",
      "updatedAt": "2024-01-10T09:00:00Z"
    },
    "productBefore": {
      "productId": "PROD-2024-200",
      "name": "무선 이어폰",
      "averageRating": 4.1,
      "totalRatingCount": 10,
      "totalRatingSum": 41
    }
  }
}</code></pre>

        <p><strong>예상 결과:</strong></p>
        <pre><code>{
  "expected": {
    "updatedRating": {
      "ratingId": "RATING-2024-100",
      "productId": "PROD-2024-200", 
      "userId": "USER-54321",
      "rating": 5,
      "createdAt": "2024-01-10T09:00:00Z",
      "updatedAt": "2024-01-15T14:30:00Z"
    },
    "updatedProduct": {
      "productId": "PROD-2024-200",
      "averageRating": 4.3,
      "totalRatingCount": 10,
      "totalRatingSum": 43
    },
    "auditLog": {
      "action": "RATING_UPDATED",
      "userId": "USER-54321",
      "productId": "PROD-2024-200",
      "oldRating": 3,
      "newRating": 5,
      "timestamp": "2024-01-15T14:30:00Z"
    }
  }
}</code></pre>
    `;

    // 데이터맵에 미리 설정 (에디터는 나중에 설정)
    dmp_unitTestDetail.set("description", demoDescription);
    dmp_unitTestDetail.set("testData", demoTestData);

    // 에디터에 시연용 내용 설정 (약간의 지연 후)
    setTimeout(function() {
        try {
            if (editor_description && editor_description.setHTML) {
                editor_description.setHTML(demoDescription);
                console.log("시연용 테스트 설명 설정 완료");
            }
            if (editor_testData && editor_testData.setHTML) {
                editor_testData.setHTML(demoTestData);
                console.log("시연용 테스트 데이터 설정 완료");
            }
        } catch(e) {
            console.error("시연용 에디터 내용 설정 실패:", e);
        }
    }, 500); // 에디터 초기화가 완료된 후 실행

    scwin.setFormMode("new");

    console.log("등록 모드 초기화 완료 - 시연용 데이터 포함");
    console.log("최종 설정된 담당자명:", currentUserName); // 사용자명으로 표시
    console.log("시연용 테스트 케이스명:", "기존 별점 업데이트 성공");

    // 임시 데이터 정리
    setTimeout(function() {
        try {
            if (window.tempPopupUserData) {
                delete window.tempPopupUserData;
            }
            var parentWindow = $p.getParentWindow();
            if (parentWindow && parentWindow.tempPopupUserData) {
                delete parentWindow.tempPopupUserData;
            }
        } catch(e) {
            console.log("임시 데이터 정리 실패:", e);
        }
    }, 1000);
};

/**
 * 수정 모드 초기화
 */
scwin.initializeEditMode = function() {
    console.log("수정 모드 초기화");

    scwin.setFormMode("edit");
    scwin.loadFileList();
};

/**
 * 부모창에서 사용자 정보 가져오기 (개선된 버전)
 */
scwin.getUserInfoFromParent = function() {
    try {
        // 1. 전역 변수에서 가져오기
        if (window.tempPopupUserData) {
            console.log("전역 변수에서 사용자 정보 가져옴:", window.tempPopupUserData);
            return window.tempPopupUserData;
        }

        // 2. 부모 창의 전역 변수에서 가져오기
        var parentWindow = $p.getParentWindow();
        if (parentWindow && parentWindow.tempPopupUserData) {
            console.log("부모 창 전역 변수에서 사용자 정보 가져옴:", parentWindow.tempPopupUserData);
            return parentWindow.tempPopupUserData;
        }

        // 3. UnitTestList.xml의 scwin에서 직접 가져오기
        if (parentWindow && parentWindow.scwin) {
            var parentScwin = parentWindow.scwin;
            if (parentScwin.CURRENT_USER_ID && parentScwin.getCurrentUserName) {
                var userInfo = {
                    currentUserId: parentScwin.CURRENT_USER_ID,
                    currentUserName: parentScwin.getCurrentUserName(),
                    currentProjectId: parentScwin.CURRENT_PROJECT_ID || "",
                    mode: "new"
                };
                console.log("부모 scwin에서 사용자 정보 가져옴:", userInfo);
                return userInfo;
            }
        }

        return null;
    } catch (e) {
        console.error("부모창에서 사용자 정보 가져오기 실패:", e);
        return null;
    }
};

/**
 * 조회 모드 초기화
 */
scwin.initializeViewMode = function() {
    console.log("조회 모드 초기화");

    scwin.setFormMode("view");
    scwin.loadFileList();
};

/**
 * 현재 사용자 이름 가져오기
 */
scwin.getCurrentUserName = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            // 메인 페이지의 헤더 프레임에서 사용자 이름 가져오기
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                var headerScwin = headerFrame.getWindow().scwin;

                // Test.xml과 동일한 방식
                if (headerScwin.USER_NAME) {
                    console.log("헤더에서 사용자 이름 가져옴:", headerScwin.USER_NAME);
                    return headerScwin.USER_NAME;
                }

                // 추가 시도: 다른 가능한 속성들
                var possibleProps = ['userName', 'currentUserName', 'userNm'];
                for (var i = 0; i < possibleProps.length; i++) {
                    var prop = possibleProps[i];
                    if (headerScwin[prop] && headerScwin[prop] !== "사용자") {
                        console.log("헤더에서 " + prop + " 가져옴:", headerScwin[prop]);
                        return headerScwin[prop];
                    }
                }
            }
        }

        // 헤더에서 가져오지 못한 경우 기본값
        console.log("헤더에서 사용자 이름을 가져올 수 없음, 기본값 사용");
        return "정개발"; // 시연용 기본 사용자명

    } catch (e) {
        console.error("사용자 이름 가져오기 실패:", e);
        return "정개발"; // 시연용 기본 사용자명
    }
};
/**
 * 서버 응답에서 사용자 정보 추출 시도
 */
scwin.getUserInfoFromServerResponse = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow) {
                var headerWindow = headerFrame.getWindow();

                // 최근 서버 응답들을 확인
                var possibleResponseObjects = [
                    'lastServerResponse',
                    'userInfo',
                    'currentUserInfo',
                    'loginInfo'
                ];

                for (var i = 0; i < possibleResponseObjects.length; i++) {
                    var propName = possibleResponseObjects[i];
                    if (headerWindow[propName] && headerWindow[propName].userName) {
                        console.log("서버 응답 객체에서 사용자명 발견:", propName, headerWindow[propName].userName);
                        return headerWindow[propName].userName;
                    }
                }

                // Test.xml의 로그를 보면 서버 응답에 userHeader가 있음
                // 최근 ajax 응답들 확인
                if (headerWindow.XMLHttpRequest && headerWindow.XMLHttpRequest.prototype) {
                    console.log("XMLHttpRequest 응답 확인 시도");
                }
            }
        }
    } catch (e) {
        console.error("서버 응답 확인 실패:", e);
    }

    return null;
};

