/**
 * 폼 모드 설정
 */
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);

    try {
        if (mode === "edit") {
            // 수정 모드
            scwin.setFieldsReadOnly(false);
            scwin.setEditorMode(true);
            scwin.showFileUploadSection(true);

            if (typeof btn_save !== 'undefined' && btn_save.show) {
                btn_save.show();
            }
            if (typeof btn_popup_edit !== 'undefined' && btn_popup_edit.hide) {
                btn_popup_edit.hide();
            }

        } else if (mode === "view") {
            // 조회 모드
            scwin.setFieldsReadOnly(true);
            scwin.setEditorMode(false);
            scwin.showFileUploadSection(false);

            if (typeof btn_save !== 'undefined' && btn_save.hide) {
                btn_save.hide();
            }
            if (typeof btn_popup_edit !== 'undefined' && btn_popup_edit.show) {
                btn_popup_edit.show();
            }
            if (typeof btn_popup_delete !== 'undefined' && btn_popup_delete.show) {
                btn_popup_delete.show();
            }

        } else if (mode === "new") {
            // 등록 모드
            scwin.setFieldsReadOnly(false);
            scwin.setEditorMode(true);
            scwin.showFileUploadSection(true);

            if (typeof btn_save !== 'undefined' && btn_save.show) {
                btn_save.show();
            }
            if (typeof btn_popup_edit !== 'undefined' && btn_popup_edit.hide) {
                btn_popup_edit.hide();
            }
            if (typeof btn_popup_delete !== 'undefined' && btn_popup_delete.hide) {
                btn_popup_delete.hide();
            }
        }
    } catch (e) {
        console.error("setFormMode 오류:", e);
    }
};

/**
 * 필드 읽기 전용 설정
