    }
};


/**
 * HTML 엔티티 완전 디코딩 (유지)
 */
scwin.fullyDecodeHtml = function(str) {
    if (!str) return str;

    var result = str;
    var attempts = 0;
    var maxAttempts = 5;

    while (attempts < maxAttempts && (result.includes('&lt;') || result.includes('&gt;') || result.includes('&quot;'))) {
        attempts++;
        var previousResult = result;

        try {
            var tempDiv = document.createElement('div');
            tempDiv.innerHTML = result;
            result = tempDiv.innerHTML;
        } catch(e) {
            // 브라우저 방식 실패 시 수동 처리
        }

        result = result
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&nbsp;/g, ' ')
            .replace(/&amp;/g, '&');

        if (result === previousResult) break;
    }

    return result;
};


/**
 * 에디터 내용 설정
 */
scwin.setEditorContent = function(description, testData) {
    try {
        if (editor_description) {
            var descContent = description || "";

            if (descContent && (descContent.includes('&lt;') || descContent.includes('&gt;') || descContent.includes('&quot;'))) {
                descContent = scwin.fullyDecodeHtml(descContent);
            }

            if (!descContent || descContent.trim() === "") {
                descContent = "<p>테스트 설명이 없습니다.</p>";
            }

            if (editor_description.setHTML) {
                editor_description.setHTML(descContent);
            }
        }

        if (editor_testData) {
            var testDataContent = testData || "";

            if (testDataContent && (testDataContent.includes('&lt;') || testDataContent.includes('&gt;') || testDataContent.includes('&quot;'))) {
                testDataContent = scwin.fullyDecodeHtml(testDataContent);
            }

            if (!testDataContent || testDataContent.trim() === "") {
                testDataContent = "<p>테스트 데이터가 없습니다.</p>";
            }

            if (editor_testData.setHTML) {
                editor_testData.setHTML(testDataContent);
            }
        }

    } catch (error) {
        console.error("에디터 내용 설정 중 오류:", error);

        try {
            if (editor_description && editor_description.setHTML) {
                editor_description.setHTML(description || "<p>내용을 불러올 수 없습니다.</p>");
            }
            if (editor_testData && editor_testData.setHTML) {
                editor_testData.setHTML(testData || "<p>내용을 불러올 수 없습니다.</p>");
            }
        } catch (fallbackError) {
            console.error("대안 방법도 실패:", fallbackError);
        }
    }
};
/**
 * 저장 버튼 클릭
 */
scwin.btn_save_onclick = function(e) {
    console.log("저장 버튼 클릭");

    // 에디터 내용을 먼저 데이터맵에 저장
    try {
        if (editor_description && editor_description.getHTML) {
            var descriptionHTML = editor_description.getHTML();
            dmp_unitTestDetail.set("description", descriptionHTML);
        }

        if (editor_testData && editor_testData.getHTML) {
            var testDataHTML = editor_testData.getHTML();
            dmp_unitTestDetail.set("testData", testDataHTML);
        }
    } catch(e) {
        console.error("에디터 내용 저장 실패:", e);
    }

    // 유효성 검사
    if (!scwin.validateForm()) {
        return;
    }

    // 현재 모드 확인
    var testCaseId = dmp_unitTestDetail.get("testCaseId");
    var isEditMode = testCaseId && testCaseId.trim() !== "";

    console.log("현재 모드:", isEditMode ? "수정" : "등록", "testCaseId:", testCaseId);

    if (isEditMode) {
        // 수정 모드
        var promise = $c.win.confirm("수정하시겠습니까?");
        promise.then(function(result) {
            if (result) {
                $c.sbm.execute($p, sbm_updateUnitTest);
            }
        });
    } else {
        // 등록 모드
        var hasFiles = false;
        if (mpd_html5Type && mpd_html5Type.fileArray) {
            hasFiles = mpd_html5Type.fileArray.length > 0;
        }

        if (hasFiles) {
            scwin.saveTestWithFiles();
        } else {
            $c.sbm.execute($p, sbm_insertUnitTest);
        }
    }
};

scwin.saveTestWithFiles = function() {
