    return true;
};
/**
 * 파일과 함께 저장
 */
scwin.executeFileUploadWithData = function() {
    console.log("executeFileUploadWithData() 시작됨");

    // 에디터 내용을 먼저 확실하게 동기화
    try {
        var descriptionHTML = "";
        var testDataHTML = "";

        if (editor_description && editor_description.getHTML) {
            descriptionHTML = editor_description.getHTML();
            dmp_unitTestDetail.set("description", descriptionHTML);
        }

        if (editor_testData && editor_testData.getHTML) {
            testDataHTML = editor_testData.getHTML();
            dmp_unitTestDetail.set("testData", testDataHTML);
        }
    } catch(e) {
        console.error("에디터 내용 가져오기 실패:", e);
    }

    // 필수 데이터 유효성 검사
    var taskId = dmp_unitTestDetail.get("taskId");
    var taskName = dmp_unitTestDetail.get("taskName");
    var testCaseName = dmp_unitTestDetail.get("testCaseName");
    var testTarget = dmp_unitTestDetail.get("testTarget");
    var projectId = dmp_unitTestDetail.get("pjtId") || scwin.CURRENT_PROJECT_ID;

    // 필수 필드 검증
    if (!taskId || taskId.trim() === "") {
        $c.win.alert("업무 ID가 없습니다. 업무를 선택해주세요.");
        return;
    }

    if (!taskName || taskName.trim() === "") {
        $c.win.alert("업무명이 없습니다. 업무를 선택해주세요.");
        return;
    }

    if (!testCaseName || testCaseName.trim() === "") {
        $c.win.alert("테스트케이스명을 입력해주세요.");
        return;
    }

    if (!testTarget || testTarget.trim() === "") {
        $c.win.alert("테스트 대상을 입력해주세요.");
        return;
    }

    if (!projectId || projectId.trim() === "") {
        $c.win.alert("프로젝트 정보가 없습니다. 프로젝트를 선택해주세요.");
        return;
    }

    console.log("필수 데이터 검증 통과");
    console.log("- taskId:", taskId);
    console.log("- taskName:", taskName);
    console.log("- testCaseName:", testCaseName);
    console.log("- testTarget:", testTarget);
    console.log("- projectId:", projectId);

    // FormData 생성 및 데이터 추가
    var formData = new FormData();

    // 필수 데이터만 추가 (기본값 없이)
    formData.append("taskId", taskId);
    formData.append("taskName", taskName);
    formData.append("testCaseName", testCaseName);
    formData.append("testTarget", testTarget);
    formData.append("pjtId", projectId);

    // 선택적 데이터 (값이 있을 때만 추가)
    var testType = dmp_unitTestDetail.get("testType");
    if (testType && testType.trim() !== "") {
        formData.append("testType", testType);
    } else {
        formData.append("testType", "NORMAL"); // 테스트 타입은 기본값 허용
    }

    var priority = dmp_unitTestDetail.get("priority");
    if (priority && priority.trim() !== "") {
        formData.append("priority", priority);
    } else {
        formData.append("priority", "MEDIUM"); // 우선순위는 기본값 허용
    }

    var testStatus = dmp_unitTestDetail.get("testStatus");
    if (testStatus && testStatus.trim() !== "") {
        formData.append("testStatus", testStatus);
    } else {
        formData.append("testStatus", "SUC"); // 테스트 상태는 기본값 허용
    }

    // 담당자 정보 (필수)
    var assignee = dmp_unitTestDetail.get("assignee") || scwin.CURRENT_USER_ID;
    if (!assignee || assignee.trim() === "") {
        $c.win.alert("담당자 정보가 없습니다.");
        return;
    }
    formData.append("assignee", assignee);

    // 선택적 필드들 (빈 값이어도 허용)
    var description = dmp_unitTestDetail.get("description") || "";
    var testData = dmp_unitTestDetail.get("testData") || "";
    var executionDate = dmp_unitTestDetail.get("executionDate") || "";
    var duration = dmp_unitTestDetail.get("duration") || "";

    formData.append("description", description);
    formData.append("testData", testData);
    formData.append("executionDate", executionDate);
    formData.append("duration", duration);

    // 파일 추가
    var hasValidFiles = false;
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;

        if (fileList && fileList.length > 0) {
            for (var i = 0; i < fileList.length; i++) {
                var fileItem = fileList[i];
                var realFile = fileItem.file || fileItem;

                if (realFile && realFile instanceof File && realFile.size > 0) {
                    formData.append("files", realFile);
                    hasValidFiles = true;
                    console.log("파일 추가 성공:", realFile.name, "크기:", realFile.size);
                }
            }
        }
    }

    console.log("유효한 파일 존재 여부:", hasValidFiles);

    // FormData 내용 확인 (디버깅용)
    console.log("=== FormData 내용 확인 ===");
    for (var pair of formData.entries()) {
        console.log(pair[0] + ': ' + (pair[1] instanceof File ? pair[1].name + ' (' + pair[1].size + ' bytes)' : pair[1]));
    }

    // 서버로 전송
    fetch("/InsWebApp/UNIT001InsWithFiles.pwkjson", {
        method: "POST",
        body: formData
    })
    .then(function(res) { 
        if (!res.ok) {
            throw new Error('HTTP ' + res.status + ': ' + res.statusText);
        }
        return res.json(); 
    })
    .then(function(res) {
        console.log("서버 응답:", res);

        var elHeader = res.elHeader;

        if (elHeader && elHeader.resSuc === true) {
            $c.win.alert("등록되었습니다.");

            // 파일 목록 초기화
            dlt_upload.setJSON([]);
            if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
                mpd_html5Type.removeAllFiles();
            }

            // 팝업 닫기
            pop_overlay.hide();

            // 목록 새로고침
            // if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
            //     scwin.searchUnitTestsByProject();
            // } else {
            //     scwin.searchUnitTests();
            // }

            scwin.searchUnitTests();
        } else {
            var errorMsg = "등록에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            if (elHeader && elHeader.resCode) {
                errorMsg += "\n오류코드: " + elHeader.resCode;
            }
            $c.win.alert(errorMsg);
        }
    })
    .catch(function(err) {
        console.error("전송 실패:", err);
        var errorMsg = "등록 중 오류가 발생했습니다.";
        if (err.message) {
            errorMsg += "\n상세 오류: " + err.message;
        }
        $c.win.alert(errorMsg);
    });
};



