/**
 * 단위테스트 삭제 완료
 */
scwin.sbm_deleteUnitTest_submitdone = function(e) {
    console.log("단위테스트 삭제 완료 (수정된 버전):", e);

    try {
        var responseData = e.responseJSON;

        // 새로운 응답 형식 처리
        if (responseData && responseData.success !== undefined) {
            if (responseData.success === true) {
                $c.win.alert("테스트 케이스가 성공적으로 삭제되었습니다.");

                if (responseData.warning) {
                    setTimeout(function() {
                        $c.win.alert("참고: " + responseData.warning);
                    }, 500);
                }

                $p.closePopup();
            } else {
                var errorMsg = responseData.message || "삭제에 실패했습니다.";
                $c.win.alert("삭제 실패:\n" + errorMsg);
            }
            return;
        }

        // 기존 응답 형식 처리 (호환성 유지)
        var elHeader = responseData ? responseData.elHeader : null;

        if (!elHeader || elHeader.resSuc == false) {
            var errorCode = elHeader ? elHeader.resCode : "알 수 없음";
            var errorMsg = elHeader ? elHeader.resMsg : "알 수 없는 오류";
            $c.win.alert(`에러코드: ${errorCode}\n에러메시지: ${errorMsg}`);
            return;
        }

        $c.win.alert("삭제되었습니다.");
        $p.closePopup();

    } catch (error) {
        console.error("삭제 응답 처리 중 오류:", error);
        $c.win.alert("삭제 응답 처리 중 오류가 발생했습니다.");
    }
};

