/**
 * 파일 그리드 셀 클릭 (미리보기)
 */
scwin.grd_fileList_oncellclick = function(row, col, colId) {
    console.log("파일 그리드 셀 클릭:", row, colId);

    var rowData = dlt_attVoList.getRowJSON(row);

    if (colId === "originalFileName") {
        scwin.previewFile(rowData.fileId, rowData.originalFileName, rowData.fileExtension);
    }
};

/**
 * 파일 그리드 액션 버튼 클릭
 */
scwin.fileActionClick = function(row, col, colId, targetId) {
    console.log("파일 액션 클릭:", row, targetId);

    var rowData = dlt_attVoList.getRowJSON(row);
    var fileId = rowData.fileId;
    var fileName = rowData.originalFileName;

    if (!fileId) {
        alert("파일 ID가 없습니다.");
        return;
    }

    if (targetId && (targetId.indexOf("download") >= 0 || targetId.indexOf("다운로드") >= 0)) {
        try {
            scwin.downloadFile(fileId, fileName);
        } catch (e) {
            console.log("기본 다운로드 실패, 대안 방법 시도:", e);
            scwin.downloadFileAlternative(fileId, fileName);
        }
    } else if (col === 3) {
        try {
            scwin.downloadFile(fileId, fileName);
        } catch (e) {
            console.log("기본 다운로드 실패, 대안 방법 시도:", e);
            scwin.downloadFileAlternative(fileId, fileName);
        }
    } else if (targetId && (targetId.indexOf("delete") >= 0 || targetId.indexOf("삭제") >= 0)) {
        scwin.deleteFile(fileId);
    } else {
        try {
            scwin.downloadFile(fileId, fileName);
        } catch (e) {
            console.log("기본 다운로드 실패, 대안 방법 시도:", e);
            scwin.downloadFileAlternative(fileId, fileName);
        }
    }
};

/**
 * 파일 미리보기
 */
scwin.previewFile = function(fileId, fileName, fileExtension) {
    console.log("파일 미리보기:", fileName, fileExtension);

    dmp_currentFile.set("fileId", fileId);
    dmp_currentFile.set("originalFileName", fileName);
    dmp_currentFile.set("fileExtension", fileExtension);

    scwin.hideAllPreviewPanels();

    var ext = fileExtension ? fileExtension.toLowerCase() : "";

    if (scwin.isImageFile(ext)) {
        scwin.showImagePreview(fileId, fileName);
    } else if (scwin.isTextFile(ext)) {
        scwin.showTextPreview(fileId, fileName);
    } else if (scwin.isDocumentFile(ext)) {
        scwin.showDocumentPreview(fileId, fileName, ext);
    } else {
        scwin.showUnsupportedPreview(fileName);
    }
};

/**
 * 파일 타입 체크
 */
scwin.isImageFile = function(ext) {
    var imageExts = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'svg', 'webp'];
    return imageExts.indexOf(ext) !== -1;
};

scwin.isTextFile = function(ext) {
    var textExts = ['txt', 'log', 'csv', 'json', 'xml', 'html', 'css', 'js', 'java', 'sql', 'properties'];
    return textExts.indexOf(ext) !== -1;
};

scwin.isDocumentFile = function(ext) {
    var docExts = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'hwp'];
    return docExts.indexOf(ext) !== -1;
};

/**
 * 미리보기 패널 제어
 */
scwin.hideAllPreviewPanels = function() {
    try {
        grp_noPreview.hide();
        grp_imagePreview.hide();
        grp_textPreview.hide();
        grp_documentPreview.hide();
    } catch(e) {
        console.error("미리보기 패널 숨기기 오류:", e);
    }
};

scwin.showNoPreview = function() {
    try {
        grp_noPreview.show();
    } catch(e) {
        console.error("기본 미리보기 표시 오류:", e);
    }
};

scwin.showImagePreview = function(fileId, fileName) {
    console.log("이미지 미리보기:", fileName);

    var imageUrl = "/InsWebApp/ImagePreview.pwkjson?fileId=" + fileId;

    try {
        txt_previewFileName.setValue(fileName);
        grp_imagePreview.show();

        setTimeout(function() {
            var imgElement = document.getElementById("img_preview");
            if (imgElement) {
                imgElement.src = imageUrl;
                imgElement.style.width = "150px";
                imgElement.style.height = "150px";
                imgElement.style.objectFit = "cover";
                imgElement.style.border = "1px solid #ddd";
                imgElement.style.background = "white";
                imgElement.style.boxShadow = "0 2px 8px rgba(0,0,0,0.1)";
                imgElement.style.borderRadius = "4px";

                imgElement.onerror = function() {
                    console.error("이미지 로드 실패:", imageUrl);
                    scwin.showUnsupportedPreview(fileName, "이미지를 로드할 수 없습니다.");
                };
            }
        }, 100);
    } catch(e) {
        console.error("이미지 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showTextPreview = function(fileId, fileName) {
    console.log("텍스트 미리보기:", fileName);

    try {
        txt_textFileName.setValue(fileName);
        grp_textPreview.show();

        fetch("/InsWebApp/FilePreview.pwkjson?fileId=" + fileId)
            .then(function(response) { return response.text(); })
            .then(function(text) {
                if (text.length > 5000) {
                    text = text.substring(0, 5000) + "\n\n... (파일 내용이 길어서 일부만 표시됩니다)";
                }
                txt_textContent.setValue(text);
            })
            .catch(function(error) {
                console.error("텍스트 파일 로드 실패:", error);
                txt_textContent.setValue("텍스트 파일을 로드할 수 없습니다.");
            });
    } catch(e) {
        console.error("텍스트 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showDocumentPreview = function(fileId, fileName, ext) {
    console.log("문서 미리보기:", fileName, ext);

    try {
        txt_documentFileName.setValue(fileName);

        var fileInfo = "";
        switch(ext) {
            case 'pdf': fileInfo = "PDF 문서 파일입니다."; break;
            case 'doc':
            case 'docx': fileInfo = "Microsoft Word 문서입니다."; break;
            case 'xls':
            case 'xlsx': fileInfo = "Microsoft Excel 스프레드시트입니다."; break;
            case 'ppt':
            case 'pptx': fileInfo = "Microsoft PowerPoint 프레젠테이션입니다."; break;
            case 'hwp': fileInfo = "한글 문서 파일입니다."; break;
            default: fileInfo = "문서 파일입니다.";
        }

        txt_documentInfo.setValue(fileInfo);
        grp_documentPreview.show();
    } catch(e) {
        console.error("문서 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showUnsupportedPreview = function(fileName, message) {
    console.log("지원하지 않는 파일 미리보기:", fileName);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 현재 미리보기 파일 다운로드
 */
scwin.downloadCurrentFile = function() {
    var fileId = dmp_currentFile.get("fileId");
    var fileName = dmp_currentFile.get("originalFileName");

    if (fileId && fileName) {
        scwin.downloadFile(fileId, fileName);
    } else {
        alert("다운로드할 파일 정보가 없습니다.");
    }
};

/**
 * 파일 다운로드
 */
scwin.downloadFile = function(fileId, fileName) {
    console.log("파일 다운로드:", fileName, "ID:", fileId);

    if (!fileId || !fileName) {
        alert("다운로드할 파일 정보가 없습니다.");
        return;
    }

    try {
        var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);

        var iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.style.position = 'absolute';
        iframe.style.left = '-9999px';
        iframe.src = downloadUrl;

        document.body.appendChild(iframe);

        setTimeout(function() {
            if (iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        }, 3000);

        console.log("파일 다운로드 요청 완료");

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        alert("파일 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};

/**
 * 파일 삭제
 */
scwin.deleteFile = function(fileId) {
    console.log("파일 삭제:", fileId);

    if (!fileId) {
        alert("삭제할 파일을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            dmp_currentFile.set("fileId", fileId);
            $c.sbm.execute($p, sbm_deleteUnitTestFile);
        }
    });
};

scwin.sbm_deleteUnitTestFile_submit = function(e) {
    var fileId = dmp_currentFile.get("fileId");
    if (!fileId) {
        console.error("삭제할 파일 ID가 없습니다.");
        return;
    }

    var deleteUrl = "/InsWebApp/UNIT001FileDelete.pwkjson?fileId=" + encodeURIComponent(fileId);
    sbm_deleteUnitTestFile.setAction(deleteUrl);
    sbm_deleteUnitTestFile.setRequestData("");
};

/**
 * 파일 삭제 완료
 */
scwin.sbm_deleteUnitTestFile_submitdone = function(e) {
    console.log("파일 삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        alert("파일 삭제 실패: " + (elHeader ? elHeader.resMsg : "알 수 없는 오류"));
        return;
    }

    alert("파일이 삭제되었습니다.");

    var deletedFileId = dmp_currentFile.get("fileId");
    if (deletedFileId) {
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        dmp_currentFile.setEmptyValue();
    }

    scwin.loadFileList();
};

/**
 * 파일 업로드 초기화
 */
scwin.btn_InitMultiupload_onclick = function(e) {
    console.log("파일 업로드 초기화");

    dlt_upload.setJSON([]);

    if (mpd_html5Type) {
        if (mpd_html5Type.clear) {
            mpd_html5Type.clear();
        } else if (mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        } else if (mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray = [];
        }
    }

    console.log("파일 업로드 초기화 완료");
};

/**
 * 업로드 파일 삭제
 */
scwin.removeUploadFile = function(row, col, colId, targetId) {
    console.log("업로드 파일 삭제:", row);

    try {
        dlt_upload.removeRow(row);

        if (mpd_html5Type && mpd_html5Type.removeFileByIndex) {
            mpd_html5Type.removeFileByIndex(row);
        } else if (mpd_html5Type && mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray.splice(row, 1);
        }

        try {
            grd_uploadList.refresh();
        } catch(e) {
            console.log("그리드 새로고침 실패, 무시");
        }

    } catch(error) {
        console.error("파일 삭제 중 오류:", error);
        alert("파일 삭제 중 오류가 발생했습니다.");
    }
};
/**
 * 개발업무에서 업무ID 클릭 시 → 테스트 조회 팝업
 */
scwin.openTestViewPopupWithTask = function(taskId, taskName) {
    console.log("업무별 테스트 조회 팝업 열기:", taskId, taskName);

    // 해당 업무의 테스트 목록 필터링
    dmp_search.set("searchTaskId", taskId);

    // 먼저 데이터 조회
    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }

    // 조회 완료 후 팝업 표시
    setTimeout(function() {
        scwin.showTestListViewPopup(taskId, taskName);
    }, 500);
};

/**
 * 조회 결과에 따른 처리
 */
scwin.showTestListViewPopup = function(taskId, taskName) {
    console.log(`업무 ${taskName} (${taskId})의 테스트 조회`);

    // 조회 결과 확인
    var successCount = dlt_successList.getTotalRow();
    var failCount = dlt_failList.getTotalRow();
    var totalCount = successCount + failCount;

    if (totalCount == 0) {
        // 테스트가 없으면 등록 확인
        var promise = $c.win.confirm(`업무 "${taskName}"에 등록된 테스트가 없습니다.\n\n새로운 테스트를 등록하시겠습니까?`);
        promise.then(function(result) {
            if (result) {
                scwin.openTestRegisterPopupWithTask(taskId, taskName);
            }
        });
    } else {
        // 테스트가 있으면 목록 표시 (현재 그리드에 이미 표시됨)
        console.log(`업무 "${taskName}"의 테스트 ${totalCount}건이 조회되었습니다.`);
        $c.win.alert(`업무 "${taskName}"의 테스트 ${totalCount}건이 조회되었습니다.\n\n성공: ${successCount}건, 실패: ${failCount}건`);
    }
};

/**
 * 개발업무에서 전달받은 업무ID로 테스트 등록 팝업 열기 (수정된 버전)
 */
scwin.openTestRegisterPopupWithTask = function(taskId, taskName) {
    console.log("개발업무 연동 테스트 등록 팝업 열기:", taskId, taskName);

    // 데이터 완전 초기화
    dmp_unitTestDetail.setEmptyValue();

    // 담당자 정보 먼저 설정
    var currentUserId = scwin.CURRENT_USER_ID || "1";
    var currentUserName = scwin.getCurrentUserName();

    console.log("개발업무 연동 시 담당자 정보:");
    console.log("- USER_ID:", currentUserId);
    console.log("- USER_NAME:", currentUserName);

    // 전달받은 업무 정보로 설정 (시연용 데이터 적용)
    dmp_unitTestDetail.set("testCaseId", "");
    dmp_unitTestDetail.set("testStatus", "SUC");
    dmp_unitTestDetail.set("priority", "HIGH"); // 시연용: 높음
    dmp_unitTestDetail.set("testType", "NORMAL");
    dmp_unitTestDetail.set("taskId", taskId);
    dmp_unitTestDetail.set("taskName", taskName); // 전달받은 업무명 우선 사용
    dmp_unitTestDetail.set("assignee", currentUserId);
    dmp_unitTestDetail.set("assigneeName", currentUserName);

    // 시연용 추가 데이터 설정
    dmp_unitTestDetail.set("testCaseName", "기존 별점 업데이트 성공");
    dmp_unitTestDetail.set("testTarget", "updateProductRating(productId, userId, newRating)");
    dmp_unitTestDetail.set("duration", "25");

    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        dmp_unitTestDetail.set("pjtId", scwin.CURRENT_PROJECT_ID);
    }

    // 나머지 초기화 코드...
    scwin.setFormMode("new");
    pop_overlay.show();

    // 팝업 타이틀은 일반적인 제목으로 설정
    setTimeout(function() {
        try {
            spn_popupTitle.setValue("새 단위테스트 케이스 등록");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("새 단위테스트 케이스 등록");
            }, 50);
        }
    }, 50);

    // 시연용 에디터 내용 설정
    setTimeout(function() {
        scwin.setDemoEditorContent();
    }, 800); // 에디터 초기화 대기

    console.log("개발업무 연동 테스트 등록 모드로 초기화 완료 - 시연용 데이터 포함");
};

