/**
 * 개발업무 파라미터 처리 (단순화된 버전)
 */
scwin.handleTaskIdParam = function() {
    try {
        var developParam = $p.getParameter("tabData");
        if (developParam && developParam.selectedTaskId) {
            console.log("개발업무에서 전달받은 업무ID:", developParam.selectedTaskId);
            console.log("개발업무에서 전달받은 flag:", developParam.openRegisterPopup);

            if (developParam.openRegisterPopup) { 
                // DevelopPopup.xml에서 등록 버튼을 누른 경우 → 테스트 등록 팝업
                scwin.openTestRegisterPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } else { 
                // DevelopList.xml에서 업무ID를 클릭한 경우 → 테스트 조회 
                scwin.openTestViewPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
        }
    } catch (e) {
        console.log("개발 업무ID 파라미터 처리 생략");
    }
};

/**
 * 팝업 닫기 콜백
 */
scwin.testPopup_closeAction = function(e) {
    console.log("테스트 팝업 닫기 콜백");

    // 목록 새로고침
    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }

    return true;
};

scwin.openTestViewOnlyPopup = function(taskId, taskName, testList) {
    console.log("테스트 조회 전용 팝업 열기:", taskId, taskName, testList);

    // 임시 데이터에 필터링된 테스트 목록 저장
    scwin.tempFilteredTests = testList;
    scwin.tempTaskInfo = { taskId: taskId, taskName: taskName };

    // 기존 팝업을 조회 모드로 설정하고 첫 번째 테스트 표시
    if (testList.length > 0) {
        dmp_unitTestDetail.setJSON(testList[0]);
        scwin.setFormMode("view");
        pop_overlay.show();

        setTimeout(function() {
            try {
                spn_popupTitle.setValue(`업무: ${taskName} - 테스트 목록 조회 (${testList.length}개)`);

                // // 팝업에 이전/다음 버튼 추가 (있다면)
                // scwin.addNavigationButtons();
            } catch(e) {
                setTimeout(function() {
                    spn_popupTitle.setValue(`업무: ${taskName} - 테스트 목록 조회 (${testList.length}개)`);
                }, 50);
            }
        }, 50);

        // 파일 목록 로드
        scwin.loadFileList();
    }
};
